// канарейка: копипаст — jscpd обязан покраснеть
func dupCanaryA() -> Int {
    let a = [1, 2, 3, 4, 5, 6, 7, 8]
    var s = 0
    for x in a where x % 2 == 0 { s += x * x + 1 }
    for x in a where x % 3 == 0 { s -= x * 2 + 3 }
    return s + a.count * 7 - a.reduce(0, +)
}

func dupCanaryB() -> Int {
    let a = [1, 2, 3, 4, 5, 6, 7, 8]
    var s = 0
    for x in a where x % 2 == 0 { s += x * x + 1 }
    for x in a where x % 3 == 0 { s -= x * 2 + 3 }
    return s + a.count * 7 - a.reduce(0, +)
}

